-- LifeLine 0.6.0 - versione applicativa + 15 modelli di chiamata (8 nuovi, 2 aggiornati)
UPDATE lifeline_settings SET value = '0.6.0' WHERE key_name = 'app_version';

SET NAMES utf8mb4;

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_003', 'Farmacia di turno', 'impropria', 1, 1, 90, 1, 'sera,notte', 0, 0, '{"code":"IMP_003","title":"Farmacia di turno","category":"impropria","phase":1,"difficulty":1,"weight":90,"min_rank":1,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"req":{"choice":[{"text":"No no, nessuna emergenza, per carità. Mi serve solo un collirio.","display":"Nessuna emergenza: cerca un collirio","detail_text":"Nessun dolore, è solo per gli occhi un po'' irritati.","detail_display":"Nessun sintomo rilevante","event":"impropria.informazioni","agencies":[]},{"text":"Beh… mia figlia ha la febbre a 39 da stasera, volevo prendere uno sciroppo.","display":"La figlia ha febbre a 39, cerca un antipiretico","detail_text":"È un po'' abbattuta ma gioca, beve, risponde normalmente.","detail_display":"Bambina vigile, beve e risponde","event":"impropria.informazioni","agencies":[]},{"text":"Ecco… è per mio marito. Ha un dolore al petto da un''ora, pensavo a un antiacido…","display":"Il marito ha dolore al petto da un''ora","detail_text":"Gli prende tutto il petto e va verso il braccio sinistro… ed è tutto sudato.","detail_display":"Dolore al petto irradiato al braccio sinistro, sudorazione","event":"sanitaria.dolore_toracico","agencies":["118"]}],"weights":[55,30,15]}},"caller":{"gender":"f","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":90,"reliability":1,"callback_chance":0.3},"opening":{"calm":"Salve, scusi il disturbo… volevo sapere qual è la farmacia di turno stanotte.","panic":"Salve, scusi… mi serve una farmacia aperta, qual è quella di turno?"},"facts":{"richiesta":{"display":"{req.display}"},"stato":{"display":"{req.detail_display}"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"}},"nodes":[{"id":"q_emergenza","label":"Per chi le serve? C''è qualcuno che sta male adesso?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{req.text}","panic":"{req.text}"}},{"id":"q_dettagli","label":"Mi descriva i sintomi: da quanto tempo e come sta adesso?","cost_s":8,"requires":["q_emergenza"],"reveals":["stato"],"reply":{"calm":"{req.detail_text}","panic":"{req.detail_text}"}},{"id":"q_dove","label":"Da dove chiama? Mi dica l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Da casa, in {location.street} {location.number}.","panic":"{location.street} {location.number}."}}],"truth":{"event_type":"{req.event}","agencies_required":["{req.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["richiesta"],"hint_debrief":"Le chiamate per informazioni vanno chiuse in fretta, ma solo dopo aver escluso un''emergenza: a volte chi chiede una farmacia sta descrivendo un infarto."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_004', 'Scherzo telefonico', 'impropria', 1, 2, 80, 1, 'pomeriggio,sera', 0, 0, '{"code":"IMP_004","title":"Scherzo telefonico","category":"impropria","phase":1,"difficulty":2,"weight":80,"min_rank":1,"time_bands":["pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro"],"floor":[0,0]},"prank":{"choice":[{"opening":"(risatine in sottofondo) Pronto… c''è un incendio… sulla Luna!","where":"Sulla Luna, gliel''ho detto! (risate)","where_display":"Dice «sulla Luna», tra le risate"},{"opening":"C''è… c''è un incendio in {location.street}! (una risata soffocata)","where":"Ehm… in {location.street}… al… al numero mille! (risate)","where_display":"{location.street} «numero mille», tra le risate"},{"opening":"Pronto, polizia? Il mio amico è stato rapito dagli alieni!","where":"Nel campo dietro la scuola… anzi no, su Marte!","where_display":"Indicazioni contraddittorie, tra le risate"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":5,"ring_patience_s":20,"hold_patience_s":10,"reliability":0.3,"callback_chance":0.15},"opening":{"calm":"{prank.opening}","panic":"{prank.opening}"},"facts":{"indirizzo":{"display":"{prank.where_display}"},"evento":{"display":"Racconto confuso, cambia versione"},"ambiente":{"label":"Rumori di fondo","display":"Risate di altri ragazzi, nessun rumore di emergenza"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente?","cost_s":5,"reveals":["indirizzo"],"reply":{"calm":"{prank.where}","panic":"{prank.where}"}},{"id":"q_ripeti","label":"Mi ripeta con calma cosa sta succedendo.","cost_s":6,"reveals":["evento"],"reply":{"calm":"Eh… c''è… c''è un problema grosso! (si sente qualcuno che gli suggerisce qualcosa)","panic":"C''è un problema grosso!"}},{"id":"q_ambiente","label":"Sento delle voci. Chi c''è lì con te?","cost_s":5,"reveals":["ambiente"],"reply":{"calm":"Nessuno! (in sottofondo: «dai, digli che…» e altre risate)","panic":"Nessuno, nessuno!"}},{"id":"q_adulto","label":"Quanti anni hai? Passami un adulto, per favore.","cost_s":5,"ends_call":true,"reply":{"calm":"(risate, poi riattaccano)","panic":"(riattaccano)"}}],"truth":{"event_type":"impropria.scherzo","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["indirizzo"],"hint_debrief":"Uno scherzo si riconosce da incoerenze e rumori di fondo; va chiuso rapidamente per liberare la linea, ma solo dopo un paio di verifiche."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_002', 'Cassonetto in fiamme', 'incendio_tecnico', 1, 1, 110, 1, 'pomeriggio,sera,notte', 1, 0, '{"code":"INC_002","title":"Cassonetto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":1,"weight":110,"min_rank":1,"time_bands":["pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"fire":{"choice":[{"text":"Un cassonetto della plastica, le fiamme saranno alte un metro.","display":"Un cassonetto, fiamme di circa un metro","danger_text":"No, è in mezzo al parcheggio, lontano da tutto.","danger_display":"Lontano da case e auto"},{"text":"Due cassonetti, e il fuoco sta arrivando a una macchina parcheggiata!","display":"Due cassonetti, fiamme vicine a un''auto","danger_text":"Sì! C''è una macchina attaccata, e sopra ci sono le finestre delle case!","danger_display":"Auto parcheggiata e finestre di abitazioni vicine"}],"weights":[65,35]},"people":{"choice":[{"text":"No, qui non c''è nessuno, solo io che guardo.","display":"Nessun ferito","agencies":[]},{"text":"Un signore ha provato a spegnerlo con un secchio e si è bruciato la mano.","display":"Un uomo si è ustionato la mano","agencies":["118"]}],"weights":[80,20]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":15,"ring_patience_s":25,"hold_patience_s":35,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un cassonetto che brucia.","panic":"Pronto! C''è un incendio qui in {location.street}, un cassonetto!"},"facts":{"indirizzo":{"display":"{location.street} altezza civico {location.number}, vicino a {location.landmark} ({location.zone_name})"},"incendio":{"display":"{fire.display}"},"pericoli":{"display":"{fire.danger_display}"},"persone":{"display":"{people.display}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Mi dia un civico o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, all''altezza del {location.number}, vicino a {location.landmark}.","panic":"In {location.street}, vicino a {location.landmark}!"}},{"id":"q_cosa","label":"Cosa sta bruciando? Quanto sono alte le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{fire.text}","panic":"{fire.text}"}},{"id":"q_vicino","label":"Il fuoco è vicino a case, auto o alberi?","cost_s":5,"requires":["q_cosa"],"reveals":["pericoli"],"reply":{"calm":"{fire.danger_text}","panic":"{fire.danger_text}"}},{"id":"q_persone","label":"Ci sono persone ferite o in pericolo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Si tenga a distanza e non provi a spegnerlo: i soccorsi stanno arrivando.","cost_s":5,"panic_delta":-10,"reply":{"calm":"D''accordo, resto qui sul marciapiede.","panic":"Va bene, va bene, mi allontano."}}],"truth":{"event_type":"incendio_tecnico.incendio_rifiuti","agencies_required":["115","{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Chiedere sempre se ci sono feriti: anche un incendio banale può richiedere il 118."},"duplicates":{"chance":0.5,"max":2,"delay_s":[20,150],"near_twin_chance":0.2},"witness_opening":{"calm":"Buonasera, c''è un cassonetto in fiamme in {location.street}, vicino a {location.landmark}.","panic":"Pronto, un incendio! Un cassonetto in {location.street}!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_009', 'Fumo da un appartamento', 'incendio_tecnico', 1, 4, 85, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_009","title":"Fumo da un appartamento","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":85,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.6,"max":2,"delay_s":[30,150],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,5]},"people":{"choice":[{"text":"Ci abita la signora Nadia, è anziana e vive da sola… ho suonato ma non risponde!","display":"Anziana sola in casa, non risponde al campanello","agencies":["115","118"]},{"text":"Credo sia al lavoro… ma sento il suo cane che abbaia come un matto.","display":"Probabilmente nessuno in casa, dentro c''è un cane","agencies":["115"]}],"weights":[60,40]}},"caller":{"gender":"f","phone_type":"any","panic_start":55,"ring_patience_s":30,"hold_patience_s":25,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, esce del fumo da sotto la porta della mia vicina, sul pianerottolo.","panic":"Pronto! C''è fumo, esce fumo dall''appartamento della vicina!"},"witness_opening":{"calm":"Buonasera, in {location.street} esce del fumo da una finestra, al {location.floor_text}.","panic":"C''è fumo che esce da una finestra in {location.street}, al {location.floor_text}!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}"},"persone":{"display":"{people.display}"},"incendio":{"display":"Fumo grigio sempre più denso, odore di bruciato, fiamme non visibili"},"pericoli":{"display":"Nessun odore di gas"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo, via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}, il {location.number}!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}, il {location.number_wrong}! Presto!"}}},{"id":"q_piano","label":"A che piano è l''appartamento?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}.","panic":"{location.floor_text}!"}},{"id":"q_persone","label":"Sa se c''è qualcuno dentro?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"q_fiamme","label":"Vede fiamme o solo fumo? Com''è il fumo?","cost_s":5,"reveals":["incendio"],"reply":{"calm":"Solo fumo grigio, ma sempre di più. Si sente puzza di bruciato.","panic":"Fumo, tanto fumo, puzza di bruciato!"}},{"id":"q_gas","label":"Sente odore di gas?","cost_s":4,"reveals":["pericoli"],"reply":{"calm":"No, gas no. Solo bruciato.","panic":"No… no, gas no."}},{"id":"a_esci","type":"reassure","label":"Non apra quella porta: esca dal palazzo con gli altri inquilini e aspetti i soccorsi fuori.","cost_s":6,"panic_delta":-18,"reply":{"calm":"D''accordo, avviso gli altri e scendo.","panic":"Sì… sì, scendo subito."}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":["{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"In un incendio in casa la domanda chiave è chi c''è dentro: una persona che non risponde richiede anche il 118. Più vicini chiamano per lo stesso fumo: vanno accorpati."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_001', 'Anziana caduta in casa', 'sanitaria', 1, 1, 120, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_001","title":"Anziana caduta in casa","category":"sanitaria","phase":1,"difficulty":1,"weight":120,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"injury":{"choice":[{"text":"Mi fa tanto male l''anca destra… la testa no, quella non l''ho battuta.","display":"Forte dolore all''anca destra, non ha battuto la testa"},{"text":"Ho battuto la testa sullo spigolo del tavolo… mi gira un po'' tutto.","display":"Ha battuto la testa, ha dei capogiri"},{"text":"Il polso… credo di essermelo rotto. La testa no.","display":"Dolore al polso, non ha battuto la testa"}]},"access":{"choice":[{"text":"No, sono sola. La porta è chiusa a chiave e le chiavi sono sul mobile dell''ingresso… non ci arrivo.","display":"Sola in casa, porta chiusa a chiave: non può aprire","agencies":["118","115"]},{"text":"Sono sola, ma la signora del piano di sopra ha le chiavi, può aprire lei.","display":"Sola; la vicina del piano di sopra ha le chiavi","agencies":["118"]},{"text":"C''è mio nipote, l''ho mandato giù ad aprire il portone.","display":"C''è il nipote, che aprirà ai soccorsi","agencies":["118"]}],"weights":[40,35,25]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":45,"hold_patience_s":70,"reliability":0.9,"callback_chance":0.7},"opening":{"calm":"Pronto? Scusi… sono caduta in cucina e non riesco più ad alzarmi.","panic":"Pronto?! Aiuto… sono caduta, non riesco ad alzarmi, mi fa male!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"Scivolata in cucina, non riesce ad alzarsi"},"ferite":{"display":"{injury.display}"},"accesso":{"label":"Accesso all''abitazione","display":"{access.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Abito in {location.street} {location.number}.","panic":"In {location.street}… il {location.number}, sì, il {location.number}."},"error":{"threshold":101,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"calm":"In {location.street} {location.number_wrong}… sì, mi pare."}}},{"id":"q_piano","label":"A che piano abita? Che nome c''è sul campanello?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}. Sul campanello c''è scritto {caller_surname}.","panic":"{location.floor_text}… {caller_surname}, c''è scritto {caller_surname}!"}},{"id":"q_cosa","label":"Mi racconti cosa è successo.","cost_s":7,"reveals":["evento"],"reply":{"calm":"Stavo prendendo un piatto, sono scivolata e sono finita per terra. Adesso non riesco a tirarmi su.","panic":"Sono scivolata! Sono per terra e non riesco ad alzarmi!"}},{"id":"q_dolore","label":"Ha male da qualche parte? Ha sbattuto la testa?","cost_s":7,"requires":["q_cosa"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_accesso","label":"C''è qualcuno con lei? Chi può aprire la porta ai soccorsi?","cost_s":7,"reveals":["accesso"],"reply":{"calm":"{access.text}","panic":"{access.text}"}},{"id":"a_rassicura","type":"reassure","label":"Signora, non si muova e stia tranquilla: le mando subito aiuto.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Va bene… grazie, grazie tanto.","panic":"Sì… sì, va bene. Faccia presto però."}}],"truth":{"event_type":"sanitaria.trauma_caduta","agencies_required":["{access.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":2400},"critical_facts":["indirizzo","accesso"],"hint_debrief":"Una persona sola che non può aprire la porta richiede anche i Vigili del fuoco per l''accesso: senza, l''ambulanza resta fuori."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_007', 'Non si sveglia (arresto cardiaco mascherato)', 'sanitaria', 1, 3, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_007","title":"Non si sveglia (arresto cardiaco mascherato)","category":"sanitaria","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,5]},"patient":{"choice":[{"rel":"marito","my":"Mio marito","him":"lo"},{"rel":"compagno","my":"Il mio compagno","him":"lo"},{"rel":"papà","my":"Mio papà","him":"lo"}]},"patient_age":{"range":[58,79]}},"caller":{"gender":"f","phone_type":"any","panic_start":65,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto? {patient.my} non si sveglia… sembra che dorma ma non mi risponde.","panic":"Pronto?! {patient.my} non si sveglia, non mi risponde! Faccia presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, citofono {caller_surname}"},"coscienza":{"display":"Non risponde e non reagisce quando lo scuote"},"respiro":{"display":"Fa dei rantoli ogni tanto, «come se russasse»"},"eta":{"display":"{patient_age} anni"},"pericoli":{"display":"Nessun odore di gas o fumo"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo esatto.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}! Venite!"},"error":{"threshold":60,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Faccia presto!"}}},{"id":"q_piano","label":"Che piano? Che nome c''è sul citofono?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, citofono {caller_surname}.","panic":"{location.floor_text}! {caller_surname}!"}},{"id":"q_coscienza","label":"Lo chiami forte e lo scuota per le spalle. Risponde?","cost_s":10,"panic_delta":5,"reveals":["coscienza"],"reply":{"calm":"No… non risponde, niente.","panic":"No! Non fa niente! Oddio!"}},{"id":"q_respiro","label":"Guardi il petto: respira normalmente?","cost_s":10,"requires":["q_coscienza"],"reveals":["respiro"],"reply":{"calm":"Fa… tipo dei rantoli, ogni tanto. Come se russasse.","panic":"Fa un rumore strano… tipo russare…"},"error":{"threshold":70,"chance":0.6,"fact":"respiro","display":"Dice che respira normalmente","reply":{"panic":"Sì, sì, respira! Cioè… credo di sì!"}}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}, credo… sì, {patient_age}!"}},{"id":"q_pericoli","label":"Sente odore di gas o fumo in casa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"No, niente.","panic":"No! Ma cosa c''entra?!"}},{"id":"a_rassicura","type":"reassure","label":"Signora, la sto aiutando. Respiri con me e mi segua.","cost_s":8,"panic_delta":-25,"reply":{"calm":"Sì… sì, va bene.","panic":"Va bene… va bene, ci provo."}}],"truth":{"event_type":"sanitaria.arresto_cardiaco","agencies_required":["118"],"agencies_acceptable":[],"severity":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"«Dorme ma non risponde» + «fa un rumore strano» indica un respiro agonico: va trasferito come arresto cardiaco appena confermati coscienza e respiro assenti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_008', 'Dolore al petto minimizzato', 'sanitaria', 1, 4, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_008","title":"Dolore al petto minimizzato","category":"sanitaria","phase":1,"difficulty":4,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"rad":{"choice":[{"text":"Beh… sì, un po'' anche sul braccio sinistro. E sudo freddo, ma sarà il caldo.","display":"Dolore che va al braccio sinistro, sudore freddo"},{"text":"No, sta qui in mezzo… però mi manca un po'' il fiato quando parlo.","display":"Dolore al centro del petto, affanno quando parla"}]},"patient_age":{"range":[56,74]}},"caller":{"gender":"m","phone_type":"any","panic_start":12,"ring_patience_s":50,"hold_patience_s":60,"reliability":0.85,"callback_chance":0.4},"opening":{"calm":"Buonasera, scusate il disturbo, niente di grave… ho un peso sullo stomaco da un paio d''ore, volevo sapere se posso prendere qualcosa.","panic":"Buonasera… scusate, ho un peso qui sul petto che non passa, volevo sapere cosa prendere."},"facts":{"dolore":{"label":"Sintomo","display":"Peso al centro del petto da circa due ore, «ma passa»"},"irradiazione":{"label":"Irradiazione","display":"{rad.display}"},"anamnesi":{"label":"Precedenti","display":"Due anni fa gli hanno messo uno stent"},"eta":{"display":"{patient_age} anni"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"accesso":{"display":"Solo in casa, dice di poter aprire"}},"nodes":[{"id":"q_sintomi","label":"Mi descriva il fastidio: dove lo sente e da quanto tempo?","cost_s":8,"reveals":["dolore"],"reply":{"calm":"Qui in mezzo al petto, tipo un peso. Da un paio d''ore… ma va e viene, eh.","panic":"In mezzo al petto, un peso… da due ore."}},{"id":"q_irradia","label":"Il dolore va verso il braccio, il collo o la mandibola? Suda?","cost_s":7,"requires":["q_sintomi"],"reveals":["irradiazione"],"reply":{"calm":"{rad.text}","panic":"{rad.text}"},"error":{"threshold":101,"fact":"irradiazione","display":"Dice che il dolore resta fermo, nessun altro sintomo","reply":{"calm":"No no, niente, sta fermo lì. Sto bene, davvero."}}},{"id":"q_storia","label":"Ha mai avuto problemi di cuore?","cost_s":5,"reveals":["anamnesi"],"reply":{"calm":"Mah, due anni fa mi hanno messo uno stent… ma da allora niente.","panic":"Uno stent, due anni fa…"}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":3,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}."}},{"id":"q_dove","label":"Mi dica l''indirizzo da cui chiama.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sono a casa, in {location.street} {location.number}. Ma non serve che mandiate qualcuno, eh.","panic":"{location.street} {location.number}."}},{"id":"q_accesso","label":"È solo? Riesce ad aprire la porta?","cost_s":5,"reveals":["accesso"],"reply":{"calm":"Sì, mia moglie è dalla sorella. Apro io, figurarsi.","panic":"Sono solo… apro io."}},{"id":"a_riposo","type":"reassure","label":"Si sieda, non faccia sforzi e apra la porta di casa: le mando un''ambulanza per sicurezza.","cost_s":7,"panic_delta":-5,"reply":{"calm":"Addirittura l''ambulanza? Va bene… se dice lei.","panic":"Va bene… grazie."}}],"truth":{"event_type":"sanitaria.dolore_toracico","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["dolore","indirizzo"],"hint_debrief":"Chi minimizza va preso sul serio: un peso al petto da ore, oltre i 50 anni e con uno stent alle spalle, è un''emergenza fino a prova contraria."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_010', 'Turista straniera, marito colto da malore', 'sanitaria', 1, 5, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_010","title":"Turista straniera, marito colto da malore","category":"sanitaria","phase":1,"difficulty":5,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro"],"floor":[1,3]},"patient_age":{"range":[64,79]}},"caller":{"gender":"f","first_pool":"names_de_f","surname_pool":"surnames_de","phone_type":"mobile","panic_start":72,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.9,"callback_chance":0.7},"opening":{"calm":"Hello? Hallo? Please… my husband… he fall, now he speak not good!","panic":"Hallo?! Hilfe! Please, my husband, he fall, he speak strange!"},"facts":{"indirizzo":{"display":"Albergo in {location.street} {location.number}, {location.floor_text}"},"evento":{"display":"Il marito è caduto in bagno, parla male, un lato della bocca è storto"},"coscienza":{"display":"Sveglio, apre gli occhi, ma non riesce a parlare bene"},"eta":{"display":"{patient_age} anni"}},"nodes":[{"id":"a_interprete","label":"Attivare il servizio di interpretariato (tedesco).","cost_s":20,"panic_delta":-15,"sets_flag":"interprete","hidden_if_flag":"interprete","reply":{"calm":"(interprete in linea) La signora si chiama {caller_first}, è tedesca, in vacanza con il marito. Traduco io.","panic":"(interprete in linea) La signora è molto agitata, si chiama {caller_first}. Traduco io."}},{"id":"q_dove","label":"Where are you? Dove vi trovate?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"},"reply_flag":{"flag":"interprete","calm":"(interprete) Sono in albergo, in {location.street} {location.number}, camera al {location.floor_text}.","panic":"(interprete) Albergo in {location.street} {location.number}, al {location.floor_text}."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"indirizzo","display":"Un albergo «vicino a {location.landmark}», via sconosciuta","reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"}}},{"id":"q_cosa","label":"What happened? Cosa è successo?","cost_s":7,"reveals":["evento"],"reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"},"reply_flag":{"flag":"interprete","calm":"(interprete) È caduto in bagno. Ora parla in modo confuso e ha la bocca storta da un lato.","panic":"(interprete) Caduto in bagno, parla male, la bocca è storta da una parte."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"evento","display":"Caduto in bagno, «parole sbagliate, faccia strana» (inglese stentato)","reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"}}},{"id":"q_coscienza","label":"Is he awake? È sveglio, le risponde?","cost_s":6,"reveals":["coscienza"],"reply":{"calm":"Yes, eyes open… but he cannot say words.","panic":"Yes… yes, but no words!"},"reply_flag":{"flag":"interprete","calm":"(interprete) Sì, è sveglio e la guarda, ma non riesce a parlare bene.","panic":"(interprete) È sveglio ma non riesce a parlare."}},{"id":"q_eta","label":"How old is he? Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}!"}},{"id":"a_calma","type":"reassure","label":"Help is coming. Stay with him. / Arrivano i soccorsi, resti con lui.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Okay… okay, danke.","panic":"Okay… please hurry!"}}],"truth":{"event_type":"sanitaria.ictus","acceptable_event_types":["sanitaria.malore","sanitaria.trauma_caduta"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","evento"],"hint_debrief":"Parola alterata e bocca storta sono segni di ictus: conta ogni minuto. L''interprete costa 20 secondi, ma senza di lui l''indirizzo resta «un albergo vicino a…»."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_012', 'Escursionista ferito, batteria scarica', 'sanitaria', 1, 6, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_012","title":"Escursionista ferito, batteria scarica","category":"sanitaria","phase":1,"difficulty":6,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","drop_after_s":[50,80],"variables":{"location":{"pool":"stradario","zones":["montagna"],"floor":[0,0]},"weather":{"choice":[{"text":"Sta calando il sole e tira un vento gelido.","display":"Sta facendo buio, vento freddo"},{"text":"C''è ancora luce, ma da ovest arriva un temporale.","display":"Luce per ora, temporale in arrivo"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":40,"hold_patience_s":15,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Pronto? Sono in montagna, mi sono fatto male a una caviglia e non riesco a camminare… ho il telefono al 3 per cento.","panic":"Pronto?! Sono bloccato in montagna, la caviglia… non cammino, e il telefono si sta spegnendo!"},"facts":{"indirizzo":{"display":"{location.street}, dopo {location.landmark}"},"ferite":{"display":"Caviglia gonfia e deformata, non riesce ad appoggiare il piede"},"pericoli":{"display":"{weather.display}"},"persone":{"display":"Da solo"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Che sentiero, cosa ha passato per ultimo?","cost_s":8,"reveals":["indirizzo"],"reply":{"calm":"Sono sul {location.street}, ho passato {location.landmark} una mezz''ora fa.","panic":"{location.street}… dopo {location.landmark}!"}},{"id":"q_ferite","label":"Com''è la caviglia? Riesce ad appoggiare il piede?","cost_s":6,"reveals":["ferite"],"reply":{"calm":"È gonfia e storta, non riesco proprio ad appoggiarla.","panic":"No! È storta, non la appoggio!"}},{"id":"q_meteo","label":"Com''è il tempo lì? Sta facendo buio?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weather.text}","panic":"{weather.text}"}},{"id":"q_solo","label":"È da solo?","cost_s":3,"reveals":["persone"],"reply":{"calm":"Sì, da solo.","panic":"Sì!"}},{"id":"a_batteria","type":"reassure","label":"Resti fermo dov''è, si copra e spenga tutto sul telefono tranne le chiamate: la troviamo noi.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Ok. Resto qui.","panic":"Ok… ok, faccio così."}}],"truth":{"event_type":"sanitaria.soccorso_impervio","acceptable_event_types":["sanitaria.trauma_caduta","incendio_tecnico.soccorso_persona"],"agencies_required":["118"],"agencies_acceptable":["CC","115"],"severity":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"critical_facts":["indirizzo","ferite"],"hint_debrief":"Con la batteria agli ultimi minuti la priorità è il luogo: poche domande mirate e trasferimento prima che la linea cada. Il cerchio AML in montagna è ampio: il punto di riferimento conta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_014', 'Bambino: la mamma non si sveglia', 'sanitaria', 1, 7, 65, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_014","title":"Bambino: la mamma non si sveglia","category":"sanitaria","phase":1,"difficulty":7,"weight":65,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,4]},"kid_age":{"range":[6,9]},"mom":{"choice":[{"text":"Ha aperto un po'' gli occhi… ma non mi risponde bene.","display":"Apre appena gli occhi, non risponde bene"},{"text":"No… non si muove…","display":"Non si muove"}]}},"caller":{"gender":"any","phone_type":"landline","panic_start":55,"ring_patience_s":25,"hold_patience_s":8,"reliability":0.7,"callback_chance":0.5},"opening":{"calm":"Pronto?… La mamma è caduta per terra e non si sveglia…","panic":"Pronto?! La mamma… la mamma non si sveglia! (piange)"},"facts":{"chiamante":{"label":"Chi chiama","display":"{caller_first}, {kid_age} anni"},"coscienza":{"display":"{mom.display}"},"respiro":{"display":"«La pancia si alza e si abbassa»"},"indirizzo":{"display":"Non ricorda la via: «vicino a {location.landmark}»"},"persone":{"display":"Solo in casa con la mamma; la vicina del piano di sopra è in casa"},"farmaci":{"label":"Terapie","display":"La mamma fa «le punture per lo zucchero»"}},"nodes":[{"id":"q_nome","label":"Come ti chiami? Quanti anni hai?","cost_s":5,"panic_delta":-10,"reveals":["chiamante"],"reply":{"calm":"{caller_first}… ho {kid_age} anni.","panic":"{caller_first}… (singhiozza) {kid_age}…"}},{"id":"q_mamma","label":"Chiama forte la mamma e toccale la spalla. Si muove?","cost_s":9,"reveals":["coscienza"],"reply":{"calm":"{mom.text}","panic":"{mom.text}"}},{"id":"q_respiro","label":"Guarda la pancia della mamma: si alza e si abbassa?","cost_s":8,"requires":["q_mamma"],"reveals":["respiro"],"reply":{"calm":"Sì… si muove su e giù.","panic":"Sì… sì, si muove."}},{"id":"q_dove","label":"Sai dirmi dove abiti? Come si chiama la tua via?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Abito vicino a {location.landmark}… la via non me la ricordo.","panic":"Non lo so! Vicino a {location.landmark}…"}},{"id":"q_adulti","label":"C''è un altro grande in casa? Un vicino che conosci?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Papà è al lavoro. La signora di sopra c''è, ha il cane.","panic":"No… la signora di sopra forse."}},{"id":"q_farmaci","label":"La mamma prende delle medicine? Fa delle punture?","cost_s":6,"reveals":["farmaci"],"reply":{"calm":"Sì, fa le punture per lo zucchero. Sulla pancia.","panic":"Le punture… per lo zucchero…"}},{"id":"a_bravo","type":"reassure","label":"Sei bravissimo. Resta vicino alla mamma: sto mandando qualcuno ad aiutarvi.","cost_s":6,"panic_delta":-22,"reply":{"calm":"Va bene… resto qui con lei.","panic":"Va bene… (tira su col naso)"}}],"truth":{"event_type":"sanitaria.incosciente","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","coscienza"],"hint_debrief":"Un bambino non sa dare l''indirizzo: con la linea fissa l''indirizzo di intestazione è decisivo. Non metterlo in attesa: riattacca dopo pochi secondi. Le «punture per lo zucchero» fanno pensare a un''ipoglicemia."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_006', 'Ladri in casa', 'sicurezza', 1, 3, 90, 1, 'mattina,sera,notte', 0, 0, '{"code":"SIC_006","title":"Ladri in casa","category":"sicurezza","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline"],"floor":[0,2]},"intruders":{"choice":[{"text":"(sussurra) Almeno due… li sento parlare. Non so se sono armati.","display":"Almeno due persone, armi non viste"},{"text":"(sussurra) Uno solo, credo… ha rotto il vetro della portafinestra.","display":"Una persona, entrata rompendo la portafinestra"}]},"car":{"choice":[{"text":"(sussurra, agitata) C''è una macchina scura col motore acceso davanti al cancello… non vedo la targa.","display":"Auto scura col motore acceso davanti al cancello"},{"text":"(sussurra) Non vedo niente… è tutto buio fuori.","display":"Nessun veicolo visibile"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":15,"reliability":0.9,"callback_chance":0.9},"opening":{"calm":"(sussurra) Pronto… ci sono dei ladri in casa. Li sento al piano di sotto.","panic":"(sussurra, con il fiato corto) Pronto… sono in casa… sono in casa, li sento!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"posizione":{"label":"Dove si trova la chiamante","display":"Chiusa a chiave in camera da letto, al piano di sopra"},"sospetti":{"display":"{intruders.display}"},"veicoli":{"display":"{car.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"(sussurra) {location.street} {location.number}.","panic":"(sussurra) {location.street}… {location.number}…"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"(sussurra) {location.street}… {location.number_wrong}…"}}},{"id":"q_posizione","label":"Lei dove si trova adesso? È al sicuro?","cost_s":6,"reveals":["posizione"],"reply":{"calm":"(sussurra) In camera, al piano di sopra. Ho chiuso la porta a chiave.","panic":"(sussurra) In camera… ho chiuso a chiave… ho paura."}},{"id":"q_quanti","label":"Quante persone sente? Ha visto armi?","cost_s":6,"reveals":["sospetti"],"reply":{"calm":"{intruders.text}","panic":"{intruders.text}"}},{"id":"q_auto","label":"Riesce a guardare dalla finestra senza farsi vedere? C''è un''auto fuori?","cost_s":12,"panic_delta":15,"reveals":["veicoli"],"reply":{"calm":"{car.text}","panic":"{car.text}"}},{"id":"a_silenzio","type":"reassure","label":"Resti dov''è, in silenzio, e non apra a nessuno. Io resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"(sussurra) Va bene… resto qui.","panic":"(sussurra) Sì… sì… non se ne vada, la prego."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","sospetti"],"hint_debrief":"Chi sussurra non può reggere lunghe attese: metterla in attesa o chiederle di muoversi aumenta il rischio. Competenza PS o CC secondo la zona."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_011', 'Lite violenta sentita dal vicino', 'sicurezza', 1, 5, 80, 1, 'sera,notte,pomeriggio', 0, 0, '{"code":"SIC_011","title":"Lite violenta sentita dal vicino","category":"sicurezza","phase":1,"difficulty":5,"weight":80,"min_rank":1,"time_bands":["sera","notte","pomeriggio"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[1,4]},"fight":{"choice":[{"text":"Un uomo che grida, una donna che piange… e prima dei colpi, come mobili che cadono.","display":"Uomo che urla, donna che piange, rumori di colpi","agencies":["{location.police}"],"event":"sicurezza.violenza_domestica"},{"text":"Adesso ho sentito lei gridare «basta, mi fai male»… e poi più niente. Silenzio.","display":"Una donna ha gridato «mi fai male», poi silenzio","agencies":["{location.police}","118"],"event":"sicurezza.violenza_domestica"}]},"weapons":{"choice":[{"text":"Non lo so… lui va a caccia, ha dei fucili, me l''aveva detto.","display":"Possibili fucili da caccia in casa"},{"text":"No, non credo.","display":"Nessuna arma nota"}],"weights":[35,65]}},"caller":{"gender":"m","phone_type":"any","panic_start":35,"ring_patience_s":45,"hold_patience_s":45,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, non so se faccio bene a chiamare… dall''appartamento accanto sento urlare da mezz''ora.","panic":"Pronto, scusate… qui di fianco stanno urlando, sento dei colpi, non so cosa fare."},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}: appartamento accanto al chiamante"},"evento":{"display":"{fight.display}"},"persone":{"display":"Coppia con una bambina piccola, probabilmente in casa"},"pericoli":{"display":"{weapons.display}"},"reazione":{"label":"Tentativo del chiamante","display":"Il chiamante ha bussato: l''uomo ha reagito con rabbia"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo e il piano.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}. È l''appartamento di fianco al mio.","panic":"{location.street} {location.number}, {location.floor_text}."}},{"id":"q_cosa","label":"Cosa sente esattamente?","cost_s":7,"reveals":["evento"],"reply":{"calm":"{fight.text}","panic":"{fight.text}"}},{"id":"q_bambini","label":"Sa chi vive in quell''appartamento? Ci sono bambini?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Una coppia, hanno una bambina piccola. Credo sia in casa.","panic":"Una coppia… con una bambina!"}},{"id":"q_armi","label":"Sa se in casa ci sono armi?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weapons.text}","panic":"{weapons.text}"}},{"id":"q_bussa","label":"Provi a bussare e a chiedere se va tutto bene.","cost_s":20,"panic_delta":25,"reveals":["reazione"],"reply":{"calm":"Ho bussato… hanno smesso, poi lui ha urlato di farmi gli affari miei. Ho paura adesso.","panic":"Ho bussato… lui mi ha urlato contro! Ho paura!"}},{"id":"a_resta","type":"reassure","label":"Resti in casa sua, chiuda la porta e non intervenga. Arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene, resto qui.","panic":"Va bene… va bene."}}],"truth":{"event_type":"{fight.event}","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":["{fight.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","evento"],"hint_debrief":"Mai mandare il chiamante a verificare di persona: si mette in pericolo e si perde tempo. Un grido di dolore seguito dal silenzio richiede anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_015', '«Vorrei ordinare una pizza»', 'sicurezza', 1, 8, 55, 3, 'sera,notte', 0, 0, '{"code":"SIC_015","title":"«Vorrei ordinare una pizza»","category":"sicurezza","phase":1,"difficulty":8,"weight":55,"min_rank":3,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,3]},"injury":{"choice":[{"text":"Sì… un po''. E anche due bibite, grazie.","display":"Conferma di essere ferita","agencies":["{location.police}","118"]},{"text":"No, per ora no.","display":"Dice di non essere ferita","agencies":["{location.police}"]}]},"weapon":{"choice":[{"text":"Sì… con le olive, grazie.","display":"Presenza di un''arma («con le olive»)"},{"text":"No, senza olive.","display":"Nessuna arma («senza olive»)"}],"weights":[40,60]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":75,"ring_patience_s":30,"hold_patience_s":8,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buonasera… vorrei ordinare una pizza. Una margherita, grande.","panic":"Buonasera… vorrei… ordinare una pizza. Margherita. Grande."},"facts":{"evento":{"display":"Conferma di essere in pericolo, parla come se ordinasse una pizza"},"sospetti":{"display":"Qualcuno con lei le sta facendo del male"},"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text} (dato «per la consegna»)"},"ferite":{"display":"{injury.display}"},"pericoli":{"display":"{weapon.display}"}},"nodes":[{"id":"q_errore","label":"Signora, ha chiamato il 112, il numero di emergenza. Ha sbagliato numero?","cost_s":6,"ends_call":true,"reply":{"calm":"(una lunga pausa) …sì. Scusi. (riattacca)","panic":"(silenzio) …sì, scusi. (riattacca)"}},{"id":"q_pericolo","label":"Ho capito. È in pericolo? Può rispondermi solo sì o no.","cost_s":6,"panic_delta":-10,"reveals":["evento"],"reply":{"calm":"Sì. Esatto, grande.","panic":"Sì… esatto. Grande."}},{"id":"q_presente","label":"C''è qualcuno lì con lei che le sta facendo del male?","cost_s":5,"requires":["q_pericolo"],"reveals":["sospetti"],"reply":{"calm":"Sì, esatto.","panic":"Sì."}},{"id":"q_indirizzo","label":"Mi dica l''indirizzo come se fosse per la consegna.","cost_s":6,"requires":["q_pericolo"],"reveals":["indirizzo"],"reply":{"calm":"Per la consegna… {location.street} {location.number}, {location.floor_text}.","panic":"{location.street}… {location.number}… {location.floor_text}."}},{"id":"q_ferita","label":"È ferita? Risponda sì o no.","cost_s":5,"requires":["q_pericolo"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_armi","label":"Lui ha un''arma? Se sì, mi dica «con le olive».","cost_s":5,"requires":["q_pericolo"],"reveals":["pericoli"],"reply":{"calm":"{weapon.text}","panic":"{weapon.text}"}},{"id":"a_resta","type":"reassure","label":"Stiamo arrivando senza sirene. Se non può parlare, lasci il telefono acceso.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Perfetto. Grazie.","panic":"…grazie."}}],"truth":{"event_type":"sicurezza.violenza_domestica","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":["{injury.agencies}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["evento","indirizzo","sospetti"],"hint_debrief":"Chi «ordina una pizza» al 112 spesso non può parlare liberamente. Domande chiuse, sì o no, e l''indirizzo chiesto «per la consegna». Dirle che ha sbagliato numero la fa riattaccare."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_005', 'Tamponamento stradale', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_005","title":"Tamponamento stradale","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"injury":{"choice":[{"text":"No, siamo tutti fuori dalle macchine, solo tanto spavento.","display":"Nessun ferito, tutti fuori dai veicoli","agencies":[],"event":"sicurezza.incidente_stradale"},{"text":"La signora dell''altra macchina dice che le fa male il collo, è ancora seduta dentro.","display":"Una donna con dolore al collo, ancora nel veicolo","agencies":["118"],"event":"sanitaria.trauma_stradale"}],"weights":[55,45]},"veh":{"choice":[{"text":"Due macchine. Niente fumo, solo il paraurti distrutto.","display":"Due auto, nessun fumo o perdita","agencies":[]},{"text":"Due macchine… e dalla mia esce del liquido sotto il motore, sento odore di benzina.","display":"Due auto, perdita di liquido e odore di benzina","agencies":["115"]}],"weights":[75,25]},"road":{"choice":[{"text":"Siamo a bordo strada, le macchine passano piano.","display":"Veicoli a bordo strada, traffico lento"},{"text":"Siamo in mezzo alla carreggiata, la gente frena all''ultimo!","display":"Veicoli in mezzo alla carreggiata, rischio di altri urti"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, buonasera. Ho appena avuto un incidente, un tamponamento.","panic":"Pronto?! C''è stato un incidente, mi hanno tamponato, qui è un casino!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"feriti":{"display":"{injury.display}"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"{road.display}"}},"nodes":[{"id":"q_dove","label":"In che strada si trova? C''è un incrocio o un punto di riferimento?","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"In {location.street}… vicino a {location.landmark}, credo!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… o forse no, non lo so, non sono di qui!"}}},{"id":"q_feriti","label":"Ci sono feriti? Qualcuno è rimasto dentro un''auto?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_veicoli","label":"Quanti veicoli sono coinvolti? Esce fumo o perdono liquidi?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"Le auto bloccano la strada? È pericoloso per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{road.text}","panic":"{road.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Accendete le quattro frecce e mettetevi al sicuro oltre il guardrail o sul marciapiede.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Sì, va bene, lo dico anche agli altri.","panic":"Ok… ok, ci spostiamo."}}],"truth":{"event_type":"{injury.event}","agencies_required":["{location.police}","{injury.agencies}","{veh.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":1800},"critical_facts":["indirizzo","feriti","veicoli"],"hint_debrief":"In un incidente la competenza tra Polizia e Carabinieri dipende dalla zona; feriti e perdite di carburante aggiungono 118 e Vigili del fuoco."},"duplicates":{"chance":0.35,"max":1,"delay_s":[30,180],"near_twin_chance":0.1},"witness_opening":{"calm":"Buonasera, in {location.street} c''è stato un tamponamento, ci sono due auto ferme.","panic":"Pronto, un incidente in {location.street}, due macchine!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_013', 'Auto fuori strada, conducente incastrato', 'sanitaria', 1, 6, 75, 2, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_013","title":"Auto fuori strada, conducente incastrato","category":"sanitaria","phase":1,"difficulty":6,"weight":75,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.7,"max":3,"delay_s":[20,160],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["colline","industriale"],"floor":[0,0]},"veh":{"choice":[{"text":"C''è un odore fortissimo di benzina, sotto la macchina c''è una pozza!","display":"Forte odore di benzina, pozza sotto l''auto"},{"text":"Esce del fumo dal cofano, sempre di più!","display":"Fumo dal cofano in aumento"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":72,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto, un''auto è finita fuori strada contro un albero, c''è uno dentro che non riesce a uscire!","panic":"Pronto! Incidente! Una macchina contro un albero, c''è uno incastrato dentro!"},"witness_opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un''auto finita contro un albero, si stanno fermando altre persone.","panic":"Pronto, in {location.street} c''è una macchina schiantata contro un albero!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"feriti":{"display":"Conducente incastrato, sanguina dalla testa, risponde a fatica"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"Auto ferma di traverso sulla carreggiata"}},"nodes":[{"id":"q_dove","label":"Dove siete esattamente? Via e punto di riferimento.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"{location.street}! Dopo {location.landmark}!"},"error":{"threshold":70,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo… non lo so!"}}},{"id":"q_feriti","label":"Quante persone sono ferite? Chi è bloccato come sta?","cost_s":7,"reveals":["feriti"],"reply":{"calm":"Solo il conducente. È incastrato, perde sangue dalla testa, risponde a fatica.","panic":"Uno! Incastrato, sangue dalla testa, parla appena!"}},{"id":"q_fuoco","label":"Esce fumo o perde carburante?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"L''auto blocca la strada? Altri rischi per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"È di traverso, le macchine devono rallentare.","panic":"È in mezzo alla strada!"}},{"id":"a_sicurezza","type":"reassure","label":"Non spostate il ferito, niente sigarette, mettetevi al sicuro fuori dalla strada.","cost_s":6,"panic_delta":-15,"reply":{"calm":"D''accordo, lo dico agli altri.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.trauma_stradale","agencies_required":["118","115","{location.police}"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"Una persona incastrata richiede i Vigili del fuoco per l''estricazione, oltre a 118 e forze dell''ordine. I testimoni che chiamano dopo vanno accorpati all''evento."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

